add("services", { slug: localized("leistungen.html", "services.html"), type: "overview", section: "services", crumbs: ["home"], children: ["strategy", "webdesign", "plone", "care"], text: localized({ title: "Vom Inhalt bis zur laufenden Pflege.", context: "Leistungen", lede: "Clara verbindet Strategie, Gestaltung, Plone-Entwicklung und Weiterentwicklung zu einem belastbaren Veröffentlichungsweg.", introTitle: "Ein System für den ganzen Lebenszyklus", intro: "Inhalte werden recherchiert, strukturiert, gestaltet, veröffentlicht und gepflegt. Wir planen diese Schritte zusammen, damit Übergaben klar und spätere Änderungen bezahlbar bleiben." }, { title: "From content strategy to ongoing care.", context: "Services", lede: "Clara connects strategy, design, Plone development and continuous improvement into a dependable publishing path.", introTitle: "One system for the full lifecycle", intro: "Content is researched, structured, designed, published and maintained. We plan these steps together so handovers stay clear and future change remains affordable." }) });
add("strategy", { slug: localized("strategie-struktur.html", "strategy-structure.html"), type: "detail", section: "services", crumbs: ["home", "services"], children: ["contentAudit", "informationArchitecture"], text: localized({ title: "Klarheit vor der ersten Gestaltung.", context: "Leistungen · Strategie & Struktur", lede: "Wir ordnen Ziele, Zielgruppen, Inhalte und redaktionelle Verantwortung, bevor daraus Seiten und Komponenten werden.", bodyTitle: "Ein gemeinsames Bild vom Inhalt", body: ["Workshops und Content-Audits machen sichtbar, was bereits funktioniert, wo Inhalte doppelt gepflegt werden und welche Fragen offen sind.", "Aus den Ergebnissen entstehen eine verständliche Informationsarchitektur, priorisierte Seitentypen und ein realistischer Veröffentlichungsplan."], deliverables: ["Content-Audit und Zielbild", "Informationsarchitektur", "Redaktionelle Rollen", "Priorisierte Roadmap"] }, { title: "Clarity before the first layout.", context: "Services · Strategy & structure", lede: "We align goals, audiences, content and editorial ownership before turning them into pages and components.", bodyTitle: "A shared view of the content", body: ["Workshops and content audits reveal what already works, where information is maintained twice and which questions remain open.", "The findings become a clear information architecture, prioritised page types and a realistic publishing plan."], deliverables: ["Content audit and target state", "Information architecture", "Editorial roles", "Prioritised roadmap"] }) });
add("contentAudit", { slug: localized("content-audit.html", "content-audit.html"), type: "detail", section: "services", crumbs: ["home", "services", "strategy"], text: localized({ title: "Ein Content-Audit schafft Überblick.", context: "Strategie & Struktur · Content-Audit", lede: "Wir prüfen Inhalte nach Nutzen, Qualität, Aktualität, Verantwortung und Aufwand.", bodyTitle: "Entscheidungen auf belastbarer Grundlage", body: ["Wir erfassen repräsentative Inhalte, Seitentypen, Suchmuster und redaktionelle Prozesse. Dabei entsteht kein endloses Inventar, sondern ein handhabbarer Blick auf Muster und Risiken.", "Jeder Befund führt zu einer Entscheidung: behalten, überarbeiten, zusammenführen, archivieren oder löschen."], deliverables: ["Repräsentatives Inventar", "Qualitätskriterien", "Verantwortungsmatrix", "Konkreter Maßnahmenplan"] }, { title: "A content audit creates a clear view.", context: "Strategy & structure · Content audit", lede: "We assess content by usefulness, quality, freshness, ownership and effort.", bodyTitle: "Decisions built on evidence", body: ["We sample content, page types, search patterns and editorial processes. The result is not an endless inventory but a manageable view of patterns and risks.", "Every finding leads to a decision: keep, improve, merge, archive or remove."], deliverables: ["Representative inventory", "Quality criteria", "Ownership matrix", "Actionable plan"] }) });
add("informationArchitecture", { slug: localized("informationsarchitektur.html", "information-architecture.html"), type: "detail", section: "services", crumbs: ["home", "services", "strategy"], text: localized({ title: "Menschen finden Inhalte über klare Wege.", context: "Strategie & Struktur · Informationsarchitektur", lede: "Begriffe, Navigation und Beziehungen orientieren sich an den Aufgaben der Besucher:innen.", bodyTitle: "Struktur, die auch wachsen kann", body: ["Card-Sorting, Suchdaten und redaktionelles Wissen helfen uns, eine gemeinsame Sprache zu finden.", "Wir testen die Struktur mit echten Aufgaben und dokumentieren Regeln für neue Inhalte, damit die Navigation nicht nach dem Relaunch zerfällt."], deliverables: ["Navigationsmodell", "Taxonomie und Begriffe", "Prototypische Klickwege", "Governance-Regeln"] }, { title: "People find content through clear paths.", context: "Strategy & structure · Information architecture", lede: "Language, navigation and relationships follow the tasks visitors need to complete.", bodyTitle: "A structure that can grow", body: ["Card sorting, search data and editorial knowledge help us establish a shared language.", "We test the structure with real tasks and document rules for new content so navigation remains coherent after launch."], deliverables: ["Navigation model", "Taxonomy and terminology", "Prototype journeys", "Governance rules"] }) });

add("webdesign", { slug: localized("webdesign.html", "web-design.html"), type: "detail", section: "services", crumbs: ["home", "services"], children: ["ux", "designSystems", "frontend"], text: localized({ title: "Webdesign für echte Inhalte.", context: "Leistungen · Webdesign", lede: "Wir entwickeln zugängliche Interfaces aus den Aufgaben von Besucher:innen und Redaktionen.", bodyTitle: "Gestaltung als belastbares System", body: ["Frühe Prototypen klären Hierarchie und Bedienung, bevor Details teuer werden. Reale Inhalte zeigen, wo Komponenten flexibel sein müssen.", "Ein überschaubares Designsystem hält Typografie, Farbe, Raum und Zustände zusammen. Es bleibt verständlich für Teams, die später damit arbeiten."], deliverables: ["UX-Konzept und Prototypen", "Visuelles Design", "Komponentenbibliothek", "Barrierefreies Frontend"] }, { title: "Web design shaped around real content.", context: "Services · Web design", lede: "We create accessible interfaces from the needs of visitors and editorial teams.", bodyTitle: "Design as a dependable system", body: ["Early prototypes clarify hierarchy and interaction before details become expensive. Real content shows where components need flexibility.", "A focused design system connects type, colour, space and states. It stays understandable for the teams who will use it later."], deliverables: ["UX concept and prototypes", "Visual design", "Component library", "Accessible frontend"] }) });
add("ux", { slug: localized("ux-prototyping.html", "ux-prototyping.html"), type: "detail", section: "services", crumbs: ["home", "services", "webdesign"], text: localized({ title: "Früh sehen, was später funktionieren muss.", context: "Webdesign · UX & Prototyping", lede: "Prototypen machen Entscheidungen sichtbar und testbar, bevor Entwicklung beginnt.", bodyTitle: "Vom Nutzungsszenario zum überprüfbaren Weg", body: ["Wir formulieren konkrete Aufgaben und bauen nur so viel Oberfläche, wie für eine belastbare Antwort nötig ist.", "Tests mit Beteiligten und Besucher:innen zeigen, wo Sprache, Reihenfolge oder Interaktion noch nicht tragen."], deliverables: ["Nutzungsszenarien", "Interaktive Prototypen", "Moderierte Tests", "Dokumentierte Entscheidungen"] }, { title: "See early what needs to work later.", context: "Web design · UX & prototyping", lede: "Prototypes make decisions visible and testable before development begins.", bodyTitle: "From scenario to a testable path", body: ["We formulate concrete tasks and build only as much interface as needed for a dependable answer.", "Testing with stakeholders and visitors reveals where language, sequence or interaction still falls short."], deliverables: ["Usage scenarios", "Interactive prototypes", "Facilitated tests", "Documented decisions"] }) });
add("designSystems", { slug: localized("designsysteme.html", "design-systems.html"), type: "detail", section: "services", crumbs: ["home", "services", "webdesign"], text: localized({ title: "Ein Designsystem hält Entscheidungen zusammen.", context: "Webdesign · Designsysteme", lede: "Wiederverwendbare Regeln und Komponenten schaffen Qualität, ohne jedes Mal neu zu beginnen.", bodyTitle: "Klein genug, um benutzt zu werden", body: ["Wir beginnen mit den wiederkehrenden Aufgaben des Projekts und entwickeln daraus Tokens, Komponenten und redaktionelle Muster.", "Dokumentation und Beispiele erklären nicht nur wie eine Komponente aussieht, sondern wann sie sinnvoll ist."], deliverables: ["Design-Tokens", "Zugängliche Komponenten", "Redaktionelle Muster", "Nutzbare Dokumentation"] }, { title: "A design system keeps decisions connected.", context: "Web design · Design systems", lede: "Reusable rules and components create quality without starting again each time.", bodyTitle: "Small enough to be used", body: ["We begin with recurring project needs and turn them into tokens, components and editorial patterns.", "Documentation and examples explain not only how a component looks but when it is useful."], deliverables: ["Design tokens", "Accessible components", "Editorial patterns", "Practical documentation"] }) });
add("frontend", { slug: localized("barrierefreies-frontend.html", "accessible-frontend.html"), type: "detail", section: "services", crumbs: ["home", "services", "webdesign"], text: localized({ title: "Barrierefreiheit gehört in jede Komponente.", context: "Webdesign · Barrierefreies Frontend", lede: "Semantisches HTML, robuste Interaktionen und schnelle Seiten machen Inhalte für mehr Menschen nutzbar.", bodyTitle: "Qualität, die sich prüfen lässt", body: ["Wir entwickeln mobile-first, testen Tastaturwege und prüfen Kontrast, Zoom, Screenreader-Ausgaben und reduzierte Bewegung.", "Performance-Budgets halten Schriften, Bilder und JavaScript in einem Rahmen, der auch unterwegs funktioniert."], deliverables: ["Semantische Templates", "WCAG-2.2-AA-Prüfung", "Responsive Komponenten", "Performance-Budget"] }, { title: "Accessibility belongs in every component.", context: "Web design · Accessible frontend", lede: "Semantic HTML, robust interactions and fast pages make content useful to more people.", bodyTitle: "Quality you can verify", body: ["We build mobile first, test keyboard paths and check contrast, zoom, screen reader output and reduced motion.", "Performance budgets keep fonts, images and JavaScript within limits that work away from fast office networks."], deliverables: ["Semantic templates", "WCAG 2.2 AA review", "Responsive components", "Performance budget"] }) });

add("plone", { slug: localized("plone-cms.html", "plone-cms.html"), type: "detail", section: "services", crumbs: ["home", "services"], children: ["migration", "integration", "workflows"], text: localized({ title: "Plone gibt anspruchsvollen Inhalten ein Zuhause.", context: "Leistungen · Plone & CMS", lede: "Sichere Rollen, strukturierte Inhalte und überprüfbare Workflows schaffen redaktionelle Unabhängigkeit.", bodyTitle: "Content Management mit langem Horizont", body: ["Plone verbindet ausgereifte Sicherheit mit flexiblen Inhaltsmodellen. Redaktionen erhalten klare Werkzeuge für komplexe Veröffentlichungsaufgaben.", "Offene Schnittstellen und eine aktive Community halten Daten zugänglich und Upgrades planbar."], deliverables: ["Content-Modelle", "Rollen und Workflows", "Integrationen", "Upgrades und Migrationen"] }, { title: "Plone gives demanding content a dependable home.", context: "Services · Plone & CMS", lede: "Secure roles, structured content and verifiable workflows create editorial independence.", bodyTitle: "Content management with a long horizon", body: ["Plone combines mature security with flexible content models. Editorial teams get clear tools for complex publishing tasks.", "Open interfaces and an active community keep data accessible and upgrades manageable."], deliverables: ["Content models", "Roles and workflows", "Integrations", "Upgrades and migrations"] }) });
add("migration", { slug: localized("migration.html", "migration.html"), type: "detail", section: "services", crumbs: ["home", "services", "plone"], text: localized({ title: "Migration ohne redaktionären Stillstand.", context: "Plone & CMS · Migration", lede: "Wir überführen Inhalte, Metadaten und Prozesse in überprüfbaren Etappen.", bodyTitle: "Jeder Schritt bleibt nachvollziehbar", body: ["Analyse und Probeläufe zeigen früh, welche Inhalte automatisiert werden können und wo redaktionelle Entscheidungen nötig sind.", "Validierungen vergleichen Quell- und Zielsystem. Redaktionen üben den neuen Ablauf, bevor die Umschaltung erfolgt."], deliverables: ["Bestandsanalyse", "Migrationsskripte", "Validierungsberichte", "Einführungsplan"] }, { title: "Migration without editorial standstill.", context: "Plone & CMS · Migration", lede: "We move content, metadata and processes in verifiable stages.", bodyTitle: "Every step stays traceable", body: ["Analysis and trial runs reveal early which content can be automated and where editorial decisions are needed.", "Validation compares source and target systems. Editorial teams rehearse the new workflow before launch."], deliverables: ["System assessment", "Migration scripts", "Validation reports", "Launch plan"] }) });
add("integration", { slug: localized("integrationen.html", "integrations.html"), type: "detail", section: "services", crumbs: ["home", "services", "plone"], text: localized({ title: "Offene Schnittstellen verbinden Plone mit der Organisation.", context: "Plone & CMS · Integrationen", lede: "Suche, Identitäten, Fachsysteme und Medienarchive werden über dokumentierte Verträge angebunden.", bodyTitle: "Verbindungen mit klarer Verantwortung", body: ["Wir definieren Datenflüsse, Fehlerfälle und Zuständigkeiten, bevor eine Schnittstelle produktiv wird.", "Monitoring und Tests machen sichtbar, wenn sich ein angebundenes System verändert."], deliverables: ["API-Konzept", "SSO und Identitäten", "Such- und Datenintegrationen", "Monitoring"] }, { title: "Open interfaces connect Plone to the organisation.", context: "Plone & CMS · Integrations", lede: "Search, identities, business systems and media archives connect through documented contracts.", bodyTitle: "Connections with clear ownership", body: ["We define data flows, failure cases and responsibilities before an interface reaches production.", "Monitoring and tests reveal when a connected system changes."], deliverables: ["API concept", "SSO and identity", "Search and data integrations", "Monitoring"] }) });
add("workflows", { slug: localized("redaktionsworkflows.html", "editorial-workflows.html"), type: "detail", section: "services", crumbs: ["home", "services", "plone"], text: localized({ title: "Workflows machen Verantwortung sichtbar.", context: "Plone & CMS · Editorial Workflows", lede: "Rollen, Freigaben und Fristen folgen dem tatsächlichen Veröffentlichungsprozess.", bodyTitle: "So einfach wie möglich, so präzise wie nötig", body: ["Wir modellieren Zuständigkeiten gemeinsam mit den Menschen, die Inhalte erstellen, prüfen und veröffentlichen.", "Übersichtliche Status, Benachrichtigungen und persönliche Arbeitslisten halten den Prozess in Bewegung."], deliverables: ["Rollenmodell", "Freigabeprozesse", "Arbeitslisten", "Redaktionshandbuch"] }, { title: "Workflows make responsibility visible.", context: "Plone & CMS · Editorial workflows", lede: "Roles, approvals and deadlines follow the real publishing process.", bodyTitle: "As simple as possible, as precise as needed", body: ["We model ownership with the people who create, review and publish content.", "Clear states, notifications and personal worklists keep the process moving."], deliverables: ["Role model", "Approval processes", "Worklists", "Editorial handbook"] }) });
add("care", { slug: localized("pflege-weiterentwicklung.html", "care-evolution.html"), type: "detail", section: "services", crumbs: ["home", "services"], children: ["support", "roadmap"], text: localized({ title: "Nach dem Launch beginnt die lange Nutzungszeit.", context: "Leistungen · Pflege & Weiterentwicklung", lede: "Regelmäßige Pflege hält Technik, Gestaltung und Inhalte gemeinsam beweglich.", bodyTitle: "Ein verlässlicher Rhythmus", body: ["Wir bündeln Support, Updates, Auswertungen und kleinere Verbesserungen in einem transparenten Arbeitsvorrat.", "Quartalsweise Roadmaps verbinden aktuelle Bedürfnisse mit Upgrades und langfristigen Zielen."], deliverables: ["Direkter Support", "Sicherheitsupdates", "Nutzungsanalyse", "Weiterentwicklungs-Roadmap"] }, { title: "Launch begins the long period of use.", context: "Services · Care & evolution", lede: "Regular care keeps technology, design and content adaptable together.", bodyTitle: "A dependable rhythm", body: ["We combine support, updates, insight and small improvements in a transparent backlog.", "Quarterly roadmaps connect current needs with upgrades and long-term goals."], deliverables: ["Direct support", "Security updates", "Usage insight", "Evolution roadmap"] }) });
add("support", { slug: localized("support.html", "support.html"), type: "detail", section: "services", crumbs: ["home", "services", "care"], text: localized({ title: "Support mit Kontext und kurzem Weg.", context: "Pflege & Weiterentwicklung · Support", lede: "Fragen erreichen Menschen, die Inhalt, Gestaltung und technische Grundlage kennen.", bodyTitle: "Lösungen fließen zurück ins System", body: ["Klare Kontakt- und Eskalationswege verkürzen die Analyse im Alltag.", "Wiederkehrende Fragen werden zu Dokumentation, Schulung oder einer dauerhaften Verbesserung."], deliverables: ["Vereinbarte Reaktionswege", "Nachvollziehbare Tickets", "Redaktionelle Hilfe", "Technische Analyse"] }, { title: "Support with context and a short path.", context: "Care & evolution · Support", lede: "Questions reach people who know the content, design and technical foundation.", bodyTitle: "Solutions feed back into the system", body: ["Clear contact and escalation paths shorten analysis in daily work.", "Recurring questions become documentation, training or a lasting improvement."], deliverables: ["Agreed response paths", "Traceable tickets", "Editorial help", "Technical analysis"] }) });
add("roadmap", { slug: localized("roadmap.html", "roadmap.html"), type: "detail", section: "services", crumbs: ["home", "services", "care"], text: localized({ title: "Eine Roadmap hält Veränderung planbar.", context: "Pflege & Weiterentwicklung · Roadmap", lede: "Verbesserungen, technische Pflege und neue Anforderungen erhalten einen gemeinsamen Horizont.", bodyTitle: "Regelmäßig entscheiden", body: ["Nutzungsdaten, Supportfragen und redaktionelle Beobachtungen liefern konkrete Kandidaten für die Weiterentwicklung.", "Gemeinsame Reviews priorisieren Wirkung, Risiko und Aufwand und machen nächste Schritte sichtbar."], deliverables: ["Quartalsreview", "Priorisierter Arbeitsvorrat", "Upgrade-Planung", "Budgetrahmen"] }, { title: "A roadmap keeps change manageable.", context: "Care & evolution · Roadmap", lede: "Improvements, technical care and new needs share one planning horizon.", bodyTitle: "Make decisions regularly", body: ["Usage data, support questions and editorial observation provide concrete candidates for improvement.", "Shared reviews prioritise impact, risk and effort and make the next steps visible."], deliverables: ["Quarterly review", "Prioritised backlog", "Upgrade planning", "Budget frame"] }) });

add("projects", { slug: localized("projekte.html", "work.html"), type: "projects", section: "projects", crumbs: ["home"], children: ["culture", "public", "business"], text: localized({ title: "Digitale Orte für öffentliche Aufgaben.", context: "Projekte", lede: "Drei fiktive Projekte zeigen, wie Clara Inhalte, Identität und technische Pflege zu einem nutzbaren Ganzen verbindet." }, { title: "Digital places for public-facing work.", context: "Work", lede: "Three fictional projects show how Clara connects content, identity and technical care into a useful whole." }) });
add("culture", { slug: localized("kultur-bildung.html", "culture-education.html"), type: "project", section: "projects", crumbs: ["home", "projects"], image: "project-culture", children: ["cityMuseum"], text: localized({ title: "Kultur & Bildung", context: "Projekte", lede: "Programme, Sammlungen und Lernangebote brauchen eine Struktur, die neugierig macht und im Alltag leicht zu pflegen ist.", bodyTitle: "Einladend für Besucher:innen, verlässlich für Teams", body: ["Clara entwickelt Inhaltsmodelle für Veranstaltungen, Sammlungen und Bildungsangebote und verbindet sie über verständliche Beziehungen.", "Flexible Landingpages geben Kampagnen Raum, ohne das Designsystem bei jeder Ausstellung neu zu erfinden."], deliverables: ["Programm- und Sammlungsmodelle", "Barrierefreie Suche", "Flexible Kampagnenseiten", "Plone-Redaktionsworkflow"] }, { title: "Culture & education", context: "Work", lede: "Programmes, collections and learning resources need a structure that invites curiosity and stays easy to maintain.", bodyTitle: "Inviting for visitors, dependable for teams", body: ["Clara creates content models for events, collections and learning resources and connects them through clear relationships.", "Flexible landing pages give campaigns room without reinventing the design system for each exhibition."], deliverables: ["Programme and collection models", "Accessible search", "Flexible campaign pages", "Plone editorial workflow"] }) });
add("cityMuseum", { slug: localized("projekt-stadtmuseum.html", "project-city-museum.html"), type: "project", section: "projects", crumbs: ["home", "projects", "culture"], image: "project-culture", text: localized({ title: "Nordhafen Stadtmuseum", context: "Projekt · Kultur & Bildung", lede: "Ein fiktives Plone-Portal verbindet Ausstellungen, Veranstaltungen und digitale Sammlung in einer zugänglichen Oberfläche.", bodyTitle: "Eine Sammlung, viele Einstiege", body: ["Besucher:innen steigen über Themen, Zeiträume und Orte ein. Verknüpfte Inhalte führen von einem Objekt zur Ausstellung und zum passenden Termin.", "Das Redaktionsteam pflegt jede Information einmal und verwendet sie in Programm, Suche und Themenwelten weiter."], deliverables: ["Content-Modell", "Sammlungssuche", "Veranstaltungskalender", "Redaktionstraining"] }, { title: "North Harbour City Museum", context: "Project · Culture & education", lede: "A fictional Plone portal connects exhibitions, events and a digital collection in one accessible interface.", bodyTitle: "One collection, many ways in", body: ["Visitors explore through themes, periods and places. Connected content leads from an object to its exhibition and related events.", "The editorial team maintains each item once and reuses it across the programme, search and thematic journeys."], deliverables: ["Content model", "Collection search", "Events calendar", "Editorial training"] }) });
add("public", { slug: localized("oeffentliche-organisationen.html", "public-organisations.html"), type: "project", section: "projects", crumbs: ["home", "projects"], image: "project-public", children: ["cityPortal"], text: localized({ title: "Öffentliche Organisationen", context: "Projekte", lede: "Verlässliche Informationen, klare Zuständigkeiten und zugängliche Services schaffen Vertrauen.", bodyTitle: "Komplexität hinter einer ruhigen Oberfläche", body: ["Wir ordnen Leistungen nach den Anliegen der Menschen und verbinden sie mit Formularen, Kontaktstellen und Rechtsgrundlagen.", "Rollen und Freigaben bilden die verteilte Verantwortung der Organisation ab."], deliverables: ["Service-Struktur", "Leichte Sprache", "Rollen und Freigaben", "Barrierefreiheit"] }, { title: "Public organisations", context: "Work", lede: "Dependable information, clear ownership and accessible services build trust.", bodyTitle: "Complexity behind a calm interface", body: ["We organise services around people's needs and connect them to forms, contact points and legal context.", "Roles and approvals reflect distributed organisational responsibility."], deliverables: ["Service structure", "Plain language", "Roles and approvals", "Accessibility"] }) });
add("cityPortal", { slug: localized("projekt-klimabuero.html", "project-climate-office.html"), type: "project", section: "projects", crumbs: ["home", "projects", "public"], image: "project-public", text: localized({ title: "Klimabüro Elbmarsch", context: "Projekt · Öffentliche Organisationen", lede: "Ein fiktives Informationsportal bündelt Beratung, Förderprogramme und lokale Klimaprojekte.", bodyTitle: "Von der Frage zur zuständigen Stelle", body: ["Eine aufgabenorientierte Navigation führt Haushalte, Initiativen und Betriebe zu passenden Angeboten.", "Strukturierte Ansprechpartner:innen und Förderinformationen bleiben an einer Stelle aktuell und erscheinen in mehreren Themenwegen."], deliverables: ["Informationsarchitektur", "Fördermittel-Datenmodell", "Standortsuche", "Redaktionsworkflow"] }, { title: "Elbe Marsh Climate Office", context: "Project · Public organisations", lede: "A fictional information portal brings advice, funding programmes and local climate projects together.", bodyTitle: "From a question to the right contact", body: ["Task-oriented navigation guides households, initiatives and businesses to suitable offers.", "Structured contacts and funding information stay current in one place and appear across multiple thematic journeys."], deliverables: ["Information architecture", "Funding content model", "Location search", "Editorial workflow"] }) });
add("business", { slug: localized("verantwortungsvolle-unternehmen.html", "responsible-business.html"), type: "project", section: "projects", crumbs: ["home", "projects"], image: "project-business", children: ["circularMaker"], text: localized({ title: "Verantwortungsvolle Unternehmen", context: "Projekte", lede: "Produkte, Wirkung und Nachweise werden verständlich, ohne Nachhaltigkeit zur Dekoration zu machen.", bodyTitle: "Aussagen mit überprüfbarer Grundlage", body: ["Produktdaten, Materialien und Zertifikate erhalten klare Inhaltsmodelle und verantwortliche Quellen.", "Fallstudien zeigen reale Entscheidungen, Produktionswege und Verbesserungen."], deliverables: ["Produktmodell", "Wirkungsnachweise", "Mehrsprachigkeit", "Content Governance"] }, { title: "Responsible business", context: "Work", lede: "Products, impact and evidence become understandable without turning sustainability into decoration.", bodyTitle: "Claims with a verifiable foundation", body: ["Product data, materials and certifications receive clear content models and responsible sources.", "Case studies explain real decisions, production paths and improvements."], deliverables: ["Product model", "Impact evidence", "Multilingual publishing", "Content governance"] }) });
add("circularMaker", { slug: localized("projekt-kreislaufwerk.html", "project-circular-works.html"), type: "project", section: "projects", crumbs: ["home", "projects", "business"], image: "project-business", text: localized({ title: "Kreislaufwerk Möbel", context: "Projekt · Verantwortungsvolle Unternehmen", lede: "Eine fiktive Produktplattform macht Materialherkunft, Reparatur und Rücknahme direkt am Produkt sichtbar.", bodyTitle: "Informationen über den gesamten Produktweg", body: ["Jedes Möbelstück verbindet Materialdaten, Pflegehinweise, Ersatzteile und Rücknahmeoptionen.", "Redaktionen können Nachweise aktualisieren, ohne Produktseiten manuell neu zusammenzustellen."], deliverables: ["Produktdatenmodell", "Dokumentenverwaltung", "Händlerbereich", "Mehrsprachige Redaktion"] }, { title: "Circular Works Furniture", context: "Project · Responsible business", lede: "A fictional product platform makes material origin, repair and take-back visible on every product.", bodyTitle: "Information across the product journey", body: ["Each piece connects material data, care guidance, spare parts and take-back options.", "Editors update evidence without manually rebuilding product pages."], deliverables: ["Product data model", "Document management", "Dealer area", "Multilingual editorial workflow"] }) });

