add("carbonBudget", { slug: localized("artikel-performance-budget.html", "article-performance-budget.html"), type: "article", section: "insights", crumbs: ["home", "insights", "magazine"], text: localized({ title: "Ein Seitenbudget macht Performance verhandelbar.", context: "Magazin · 8 Minuten", lede: "Klare Grenzen für Bilder, Schriften und JavaScript helfen Teams, Geschwindigkeit über Jahre zu erhalten.", bodyTitle: "Budget statt einmaliger Optimierung", body: ["Ein schneller Launch bleibt nicht automatisch schnell. Neue Kampagnen, Tracking-Skripte und Bildformate erhöhen das Gewicht schrittweise.", "Ein gemeinsames Budget benennt Grenzwerte, Verantwortliche und Ausnahmen. Regelmäßige Messungen machen Abweichungen sichtbar, bevor sie zur Normalität werden."], deliverables: ["Zielwerte pro Seitentyp", "Messung im Build", "Regeln für Ausnahmen", "Regelmäßige Reviews"] }, { title: "A page budget makes performance negotiable.", context: "Journal · 8 minute read", lede: "Clear limits for images, fonts and JavaScript help teams preserve speed over time.", bodyTitle: "A budget, not a one-off optimisation", body: ["A fast launch does not stay fast automatically. Campaigns, tracking scripts and image formats add weight over time.", "A shared budget names thresholds, owners and exceptions. Regular measurement reveals drift before it becomes normal."], deliverables: ["Targets by page type", "Build-time measurement", "Exception rules", "Regular reviews"] }) });
add("contentGovernance", { slug: localized("artikel-content-governance.html", "article-content-governance.html"), type: "article", section: "insights", crumbs: ["home", "insights", "magazine"], text: localized({ title: "Content Governance beginnt mit einer klaren Frage.", context: "Magazin · 6 Minuten", lede: "Wer entscheidet, ob ein Inhalt noch gebraucht wird?", bodyTitle: "Verantwortung lässt sich gestalten", body: ["Gute Governance besteht nicht aus einem dicken Regelwerk. Sie verbindet Inhaltstypen mit Verantwortlichen, Prüfzyklen und einer sichtbaren nächsten Aktion.", "Plone kann diese Regeln mit Rollen, Workflows und Erinnerungen unterstützen. Die fachliche Entscheidung bleibt bei den Teams."], deliverables: ["Verantwortliche Rollen", "Prüfzyklen", "Archivierungsregeln", "Unterstützende Workflows"] }, { title: "Content governance begins with one clear question.", context: "Journal · 6 minute read", lede: "Who decides whether a piece of content is still needed?", bodyTitle: "Responsibility can be designed", body: ["Good governance is not a thick rulebook. It connects content types to owners, review cycles and a visible next action.", "Plone can support these rules through roles, workflows and reminders. Subject decisions stay with the teams."], deliverables: ["Responsible roles", "Review cycles", "Archiving rules", "Supporting workflows"] }) });
