add("editorialGuide", { slug: localized("leitfaden-redaktionssystem.html", "guide-editorial-system.html"), type: "article", section: "insights", crumbs: ["home", "insights", "guides"], text: localized({ title: "Sieben Fragen vor der CMS-Auswahl.", context: "Leitfaden · PDF und Web", lede: "Ein gutes CMS passt zu Verantwortung, Inhalt und erwarteter Lebensdauer.", bodyTitle: "Die Auswahl beginnt bei der Organisation", body: ["Technische Funktionslisten beantworten selten, wie ein Team tatsächlich veröffentlicht. Rollen, Freigaben, Mehrsprachigkeit und Pflegeaufwand sind die bessere Grundlage.", "Der Leitfaden hilft, diese Fragen vor einer Produktauswahl gemeinsam zu klären."], deliverables: ["Rollen und Rechte", "Inhaltsmodelle", "Integrationen", "Betrieb und Upgrade"] }, { title: "Seven questions before choosing a CMS.", context: "Guide · PDF and web", lede: "A good CMS fits the organisation's responsibility, content and expected lifetime.", bodyTitle: "Selection begins with the organisation", body: ["Technical feature lists rarely explain how a team actually publishes. Roles, approvals, multilingual needs and maintenance effort provide a better foundation.", "The guide helps teams clarify these questions together before selecting a product."], deliverables: ["Roles and permissions", "Content models", "Integrations", "Operations and upgrades"] }) });
add("workshops", { slug: localized("workshops.html", "workshops.html"), type: "detail", section: "insights", crumbs: ["home", "insights"], text: localized({ title: "Workshops bringen Entscheidungen in Bewegung.", context: "Wissen · Workshops", lede: "Kompakte Formate zu Content-Strategie, Informationsarchitektur, Plone und nachhaltigem Webdesign.", bodyTitle: "Arbeit an einer realen Frage", body: ["Jeder Workshop beginnt mit einem konkreten Ziel und vorhandenen Materialien aus Ihrer Organisation.", "Am Ende stehen dokumentierte Entscheidungen, offene Fragen und ein nächster Schritt, den das Team selbst tragen kann."], deliverables: ["Halb- oder ganztägig", "Remote oder vor Ort", "Deutsch oder Englisch", "Dokumentierte Ergebnisse"] }, { title: "Workshops move decisions forward.", context: "Insights · Workshops", lede: "Focused formats for content strategy, information architecture, Plone and sustainable web design.", bodyTitle: "Work on a real question", body: ["Every workshop begins with a concrete goal and existing material from your organisation.", "The outcome is a set of documented decisions, open questions and a next step the team can own."], deliverables: ["Half or full day", "Remote or on site", "German or English", "Documented outcomes"] }) });

