add("approach", { slug: localized("arbeitsweise.html", "approach.html"), type: "detail", section: "studio", crumbs: ["home", "studio"], text: localized({ title: "Gemeinsam sehen, entscheiden und liefern.", context: "Studio · Arbeitsweise", lede: "Kurze Arbeitszyklen halten Fachwissen, Inhalt und technische Entscheidungen nah beieinander.", bodyTitle: "Ein sichtbarer Arbeitsstand", body: ["Wir arbeiten mit realen Inhalten und klickbaren Zwischenständen. Entscheidungen werden dort getroffen, wo ihre Wirkung sichtbar ist.", "Regelmäßige Reviews verbinden Projektteam und Verantwortliche. Dokumentation entsteht während der Arbeit und bleibt Teil des Ergebnisses."], deliverables: ["Wöchentliche Zwischenstände", "Gemeinsame Reviews", "Offene Dokumentation", "Planbare Übergaben"] }, { title: "See, decide and deliver together.", context: "Studio · Approach", lede: "Short working cycles keep subject knowledge, content and technical decisions close together.", bodyTitle: "Visible work in progress", body: ["We work with real content and clickable increments. Decisions happen where their effect is visible.", "Regular reviews connect the delivery team and responsible stakeholders. Documentation grows with the work and remains part of the outcome."], deliverables: ["Weekly increments", "Shared reviews", "Open documentation", "Planned handovers"] }) });
add("responsibility", { slug: localized("verantwortung.html", "responsibility.html"), type: "detail", section: "studio", crumbs: ["home", "studio"], text: localized({ title: "Nachhaltigkeit ist eine Reihe überprüfbarer Entscheidungen.", context: "Studio · Verantwortung", lede: "Wir reduzieren Daten, Abhängigkeiten und unnötige Neuentwicklung und planen Pflege von Anfang an mit.", bodyTitle: "Wirkung in Betrieb und Nutzung", body: ["Performance-Budgets, optimierte Medien und zurückhaltendes JavaScript senken Übertragung und Energiebedarf.", "Offene Standards, zugängliche Komponenten und dokumentierte Upgrade-Wege schützen die Investition der Organisation."], deliverables: ["Performance-Budget", "CO₂-bewusstes Hosting", "Offene Standards", "Langfristige Wartung"] }, { title: "Sustainability is a series of verifiable decisions.", context: "Studio · Responsibility", lede: "We reduce data, dependencies and unnecessary redevelopment and plan for maintenance from the start.", bodyTitle: "Impact in operation and use", body: ["Performance budgets, optimised media and restrained JavaScript reduce transfer and energy demand.", "Open standards, accessible components and documented upgrade paths protect the organisation's investment."], deliverables: ["Performance budget", "Carbon-aware hosting", "Open standards", "Long-term maintenance"] }) });
add("partners", { slug: localized("partner-netzwerk.html", "partners-network.html"), type: "detail", section: "studio", crumbs: ["home", "studio"], text: localized({ title: "Das passende Team für die konkrete Aufgabe.", context: "Studio · Partner & Netzwerk", lede: "Für Forschung, Text, Illustration und Spezialentwicklung arbeiten wir mit einem vertrauten Netzwerk.", bodyTitle: "Verantwortung bleibt klar", body: ["Partner:innen werden nach Aufgabe und Erfahrung ausgewählt und von Beginn an in den Arbeitsprozess eingebunden.", "Clara bleibt für Koordination, Qualität und Übergabe verantwortlich. Verträge und Ergebnisse sind transparent."], deliverables: ["Erprobtes Netzwerk", "Klare Ansprechpartner:innen", "Faire Zusammenarbeit", "Offene Ergebnisse"] }, { title: "The right team for the specific task.", context: "Studio · Partners & network", lede: "For research, writing, illustration and specialist development, we work with a trusted network.", bodyTitle: "Responsibility remains clear", body: ["Partners are selected for the task and their experience and join the working process from the beginning.", "Clara remains responsible for coordination, quality and handover. Contracts and outcomes are transparent."], deliverables: ["Experienced network", "Clear contacts", "Fair collaboration", "Open outcomes"] }) });

