const t = (route, lang) => route.text[lang];
const href = (key, lang) => routes[key].slug[lang];
const esc = (value = "") => String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
const image = (name, alt, options = {}) => `<picture class="${options.className || "media"}"><source type="image/avif" srcset="../assets/images/${name}.avif"><img src="../assets/images/${name}.jpg" width="${options.width || 1200}" height="${options.height || 900}" alt="${esc(alt)}" ${options.eager ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async"></picture>`;

function mega(group, lang, current) {
  const links = group.items.map(([key, label, description, subs = []]) => `<li>
    <a class="mega-main" href="${href(key, lang)}"${current === key ? ' aria-current="page"' : ""}><span><strong>${label}</strong><span>${description}</span></span><span aria-hidden="true">↗</span></a>
    ${subs.length ? `<ul class="mega-sub" aria-label="${esc(label)}">${subs.map(([subKey, subLabel]) => `<li><a href="${href(subKey, lang)}"${current === subKey ? ' aria-current="page"' : ""}>${subLabel}</a></li>`).join("")}</ul>` : ""}
  </li>`).join("");
  return `<li class="nav-item"><details class="nav-disclosure" data-nav-details${routes[current].section === group.key ? ' data-current="true"' : ""}>
    <summary>${group.label}<span class="chevron" aria-hidden="true"></span></summary>
    <div class="mega-panel"><div class="shell mega-grid">
      <div class="mega-intro"><a class="mega-title" href="${href(group.key, lang)}">${group.label}<span aria-hidden="true">→</span></a><p>${group.intro}</p><p class="mega-proof">${group.proof}</p></div>
      <ul class="mega-list">${links}</ul>
    </div></div>
  </details></li>`;
}

function header(route, lang) {
  const c = copy[lang];
  const other = lang === "de" ? "en" : "de";
  return `<a class="skip-link" href="#main">${c.skip}</a>
<header class="site-header" data-header>
  <div class="header-shell shell">
    <a class="brand" href="${href("home", lang)}" aria-label="Clara Design Studio · ${c.home}"><span class="brand-window" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>Clara <b>Design Studio</b></span></a>
    <button class="menu-toggle" type="button" data-menu-toggle aria-expanded="false" aria-controls="primary-navigation"><span class="menu-icon" aria-hidden="true"></span><span>${c.menu}</span></button>
    <nav class="site-nav" id="primary-navigation" aria-label="${lang === "de" ? "Hauptnavigation" : "Primary navigation"}"><ul class="primary-nav">
      ${nav[lang].map((group) => mega(group, lang, route.key)).join("")}
      <li class="nav-item"><a class="direct-link" href="${href("contact", lang)}"${route.section === "contact" ? ' aria-current="page"' : ""}>${lang === "de" ? "Kontakt" : "Contact"}</a></li>
    </ul></nav>
    <div class="utility"><a href="${href("search", lang)}"${route.section === "search" ? ' aria-current="page"' : ""}>${c.search}</a><span aria-hidden="true">·</span><a href="../${other}/${href(route.key, other)}" lang="${other}" hreflang="${other}">${c.other}</a></div>
  </div>
</header>`;
}

function breadcrumbs(route, lang) {
  if (route.key === "home") return "";
  const items = route.crumbs.map((key) => `<li><a href="${href(key, lang)}">${key === "home" ? copy[lang].home : esc(t(routes[key], lang).context.split(" · ").at(-1))}</a></li>`).join("");
  return `<nav class="breadcrumbs shell" aria-label="${lang === "de" ? "Brotkrümelnavigation" : "Breadcrumb"}"><ol>${items}<li aria-current="page">${esc(t(route, lang).context.split(" · ").at(-1))}</li></ol></nav>`;
}

function pageHero(route, lang) {
  const text = t(route, lang);
  return `<header class="page-hero page-hero--${route.section}"><div class="shell page-hero-grid"><p class="context">${text.context}</p><h1>${text.title}</h1><p class="lede">${text.lede}</p></div></header>`;
}

