function childLinks(route, lang) {
  if (!route.children?.length) return "";
  return `<section class="related shell"><h2>${lang === "de" ? "Weiter ins Thema" : "Explore this area"}</h2><ul>${route.children.map((key) => `<li><a href="${href(key, lang)}"><span>${t(routes[key], lang).title}</span><span aria-hidden="true">→</span></a></li>`).join("")}</ul></section>`;
}

function home(route, lang) {
  const c = copy[lang];
  const de = lang === "de";
  return `<main id="main">
<section class="home-hero"><div class="shell hero-grid"><div class="hero-copy"><p class="context">${t(route, lang).context}</p><h1>${t(route, lang).title}</h1><p class="lede">${t(route, lang).lede}</p><div class="actions"><a class="button button--ink" href="${href("contact", lang)}">${c.projectCta}</a><a class="text-link" href="${href("approach", lang)}">${c.secondaryCta}</a></div></div><div class="hero-picture-wrap"><picture class="hero-picture"><source media="(max-width: 55.99rem)" type="image/avif" srcset="../assets/images/hero-portrait.avif"><source media="(max-width: 55.99rem)" type="image/jpeg" srcset="../assets/images/hero-portrait.jpg"><source type="image/avif" srcset="../assets/images/hero-wide.avif"><img src="../assets/images/hero-wide.jpg" width="1800" height="1180" alt="${de ? "Heller Büroflur mit Glaswänden und warmem Tageslicht" : "Bright office corridor with glass walls and warm daylight"}" fetchpriority="high" decoding="async"></picture><div class="hero-note"><b>${de ? "Offen für neue Projekte" : "Open for new projects"}</b><span>${de ? "Herbst 2026" : "Autumn 2026"}</span></div></div></div></section>
<section class="lifecycle section"><div class="shell"><div class="section-intro"><h2>${de ? "Ein guter Webauftritt bleibt in Bewegung." : "A good website keeps moving."}</h2><p>${de ? "Clara gestaltet nicht nur den sichtbaren Launch. Wir verbinden vier Aufgaben zu einem belastbaren Content-System." : "Clara designs more than the visible launch. We connect four responsibilities into a dependable content system."}</p></div><ol class="lifecycle-list">
  <li><b>01</b><div><h3>${de ? "Verstehen" : "Understand"}</h3><p>${de ? "Ziele, Menschen und vorhandene Inhalte." : "Goals, people and existing content."}</p></div></li>
  <li><b>02</b><div><h3>${de ? "Ordnen" : "Structure"}</h3><p>${de ? "Begriffe, Wege und Verantwortung." : "Language, journeys and ownership."}</p></div></li>
  <li><b>03</b><div><h3>${de ? "Gestalten" : "Design"}</h3><p>${de ? "Zugängliche Komponenten mit echten Inhalten." : "Accessible components using real content."}</p></div></li>
  <li><b>04</b><div><h3>${de ? "Pflegen" : "Care"}</h3><p>${de ? "Messen, aktualisieren und sinnvoll erweitern." : "Measure, update and evolve with purpose."}</p></div></li>
</ol></div></section>
<section class="service-map section"><div class="shell"><div class="section-intro"><h2>${de ? "Vier Perspektiven. Ein Veröffentlichungsweg." : "Four perspectives. One publishing path."}</h2><p>${de ? "Jede Leistung hat eine eigene Aufgabe. Zusammen halten sie Inhalte langfristig nutzbar." : "Each service has a distinct role. Together they keep content useful over time."}</p></div><div class="service-bands">${["strategy", "webdesign", "plone", "care"].map((key) => { const color = serviceMeta[key]; const item = t(routes[key], lang); return `<a class="service-band service-band--${color}" href="${href(key, lang)}"><h3>${item.context.split(" · ").at(-1)}</h3><p>${item.lede}</p><b aria-hidden="true">↗</b></a>`; }).join("")}</div></div></section>
<section class="projects-home section"><div class="shell"><div class="section-intro section-intro--row"><div><h2>${de ? "Websites für Arbeit, die öffentlich zählt." : "Websites for work that matters in public."}</h2><p>${de ? "Fiktive Projekte, reale Anforderungen." : "Fictional projects, real requirements."}</p></div><a class="text-link" href="${href("projects", lang)}">${de ? "Alle Projekte" : "All work"}</a></div><div class="project-mosaic">
<a class="project-feature" href="${href("cityMuseum", lang)}">${image("project-culture", de ? "Modernes Gebäude mit Bäumen im Abendlicht" : "Modern building with trees in the evening light")}<span><b>${de ? "Nordhafen Stadtmuseum" : "North Harbour City Museum"}</b><small>${de ? "Sammlung · Programm · Plone" : "Collection · Programme · Plone"}</small></span></a>
<a class="project-small project-small--sky" href="${href("cityPortal", lang)}"><span><small>${de ? "Öffentliche Information" : "Public information"}</small><b>${de ? "Klimabüro Elbmarsch" : "Elbe Marsh Climate Office"}</b><em aria-hidden="true">↗</em></span>${image("project-public", de ? "Heller Besprechungsraum mit großen Fenstern" : "Bright meeting room with large windows")}</a>
<a class="project-small project-small--sun" href="${href("circularMaker", lang)}">${image("project-business", de ? "Helles Studio mit Sitzgruppen und hohen Fenstern" : "Bright studio with seating areas and tall windows")}<span><small>${de ? "Verantwortungsvolle Produkte" : "Responsible products"}</small><b>${de ? "Kreislaufwerk Möbel" : "Circular Works Furniture"}</b><em aria-hidden="true">↗</em></span></a>
</div></div></section>
<section class="statement"><div class="shell statement-grid"><p>${de ? "Nachhaltiges Content Management heißt:" : "Sustainable content management means:"}</p><h2>${de ? "Inhalte einmal gut strukturieren, verantwortlich pflegen und auf vielen Wegen weiterverwenden." : "Structure content well once, maintain it responsibly and reuse it across many journeys."}</h2><a class="button button--ink" href="${href("responsibility", lang)}">${de ? "Unsere Verantwortung" : "Our responsibility"}</a></div></section>
<section class="insight-tease section"><div class="shell"><div class="section-intro section-intro--row"><div><h2>${de ? "Notizen für den nächsten guten Schritt." : "Notes for the next useful step."}</h2><p>${de ? "Aus unserer Arbeit an Inhalt, Technik und Verantwortung." : "From our work across content, technology and responsibility."}</p></div><a class="text-link" href="${href("insights", lang)}">${de ? "Alles Wissen" : "All insights"}</a></div><ul class="article-list"><li><a href="${href("carbonBudget", lang)}"><span>${de ? "Performance" : "Performance"}</span><strong>${t(routes.carbonBudget, lang).title}</strong><em>${de ? "8 Minuten" : "8 min"}</em></a></li><li><a href="${href("contentGovernance", lang)}"><span>Content</span><strong>${t(routes.contentGovernance, lang).title}</strong><em>${de ? "6 Minuten" : "6 min"}</em></a></li><li><a href="${href("editorialGuide", lang)}"><span>${de ? "Leitfaden" : "Guide"}</span><strong>${t(routes.editorialGuide, lang).title}</strong><em>PDF + Web</em></a></li></ul></div></section>
</main>`;
}

function overview(route, lang) {
  const text = t(route, lang);
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell overview-intro"><h2>${text.introTitle}</h2><p>${text.intro}</p></div><div class="shell overview-rows">${route.children.map((key, index) => { const child = t(routes[key], lang); const color = serviceMeta[key] || ["sun", "sky", "leaf", "coral"][index % 4]; return `<a class="overview-row overview-row--${color}" href="${href(key, lang)}"><h3>${child.context.split(" · ").at(-1)}</h3><p>${child.lede}</p><span aria-hidden="true">↗</span></a>`; }).join("")}</div></section></main>`;
}

function detail(route, lang) {
  const text = t(route, lang);
  const de = lang === "de";
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="detail section"><div class="shell detail-grid"><article class="prose"><h2>${text.bodyTitle}</h2>${text.body.map((p) => `<p>${p}</p>`).join("")}</article><aside class="deliverables"><h2>${de ? "Was entsteht" : "What we deliver"}</h2><ul>${text.deliverables.map((item) => `<li><span aria-hidden="true">✓</span>${item}</li>`).join("")}</ul><a class="button button--coral" href="${href("contact", lang)}">${copy[lang].projectCta}</a></aside></div></section>${childLinks(route, lang)}</main>`;
}

function projects(route, lang) {
  const de = lang === "de";
  const entries = [["culture", "project-culture", de ? "Modernes Gebäude mit Bäumen im Abendlicht" : "Modern building with trees in the evening light", "sun"], ["public", "project-public", de ? "Heller Besprechungsraum mit großen Fenstern" : "Bright meeting room with large windows", "sky"], ["business", "project-business", de ? "Helles Studio mit Sitzgruppen" : "Bright studio with seating areas", "leaf"]];
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell project-index">${entries.map(([key, img, alt, color], index) => `<article class="project-row project-row--${color}">${image(img, alt)}<div><span>${String(index + 1).padStart(2, "0")}</span><h2>${t(routes[key], lang).title}</h2><p>${t(routes[key], lang).lede}</p><a class="text-link" href="${href(key, lang)}">${de ? "Projekte entdecken" : "Explore projects"}</a></div></article>`).join("")}</div></section></main>`;
}

function project(route, lang) {
  const text = t(route, lang);
  const de = lang === "de";
  const alt = route.image === "project-culture" ? (de ? "Modernes Gebäude mit Bäumen im Abendlicht" : "Modern building with trees in the evening light") : route.image === "project-public" ? (de ? "Heller Besprechungsraum mit großen Fenstern" : "Bright meeting room with large windows") : (de ? "Helles Studio mit Sitzgruppen und hohen Fenstern" : "Bright studio with seating areas and tall windows");
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<div class="shell project-hero-image">${image(route.image, alt)}</div><section class="detail section"><div class="shell detail-grid"><article class="prose"><h2>${text.bodyTitle}</h2>${text.body.map((p) => `<p>${p}</p>`).join("")}</article><aside class="deliverables"><h2>${de ? "Bausteine" : "Building blocks"}</h2><ul>${text.deliverables.map((item) => `<li><span aria-hidden="true">✓</span>${item}</li>`).join("")}</ul><a class="button button--coral" href="${href("contact", lang)}">${copy[lang].projectCta}</a></aside></div></section>${childLinks(route, lang)}</main>`;
}

function insights(route, lang) {
  const de = lang === "de";
  const keys = route.key === "magazine" ? ["carbonBudget", "contentGovernance"] : route.key === "guides" ? ["editorialGuide"] : ["carbonBudget", "contentGovernance", "editorialGuide", "workshops"];
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell"><ul class="article-list article-list--large">${keys.map((key, index) => `<li><a href="${href(key, lang)}"><span>${index % 2 ? "Content" : (de ? "Praxis" : "Practice")}</span><strong>${t(routes[key], lang).title}</strong><p>${t(routes[key], lang).lede}</p><em aria-hidden="true">↗</em></a></li>`).join("")}</ul></div></section></main>`;
}

function studio(route, lang) {
  const de = lang === "de";
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell studio-grid">${image("studio-plants", de ? "Große grüne Blätter im Tageslicht" : "Large green leaves in daylight")}<div><h2>${de ? "Design, Inhalt und Technik an einem Tisch." : "Design, content and technology at one table."}</h2><p>${de ? "Clara ist bewusst klein. Für jede Aufgabe arbeiten die Menschen zusammen, die Entscheidungen treffen und umsetzen können." : "Clara is deliberately small. Each project brings together the people who can make and implement decisions."}</p><p>${de ? "Für Spezialaufgaben ergänzt ein vertrautes Netzwerk das Kernteam. Verantwortung und Ansprechpartner:innen bleiben klar." : "A trusted network adds specialist knowledge when needed. Responsibility and contacts remain clear."}</p></div></div></section>${childLinks(route, lang)}</main>`;
}

function contact(route, lang) {
  const de = lang === "de";
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell contact-grid"><div class="contact-aside"><h2>${de ? "Was Sie erwarten können" : "What to expect"}</h2><ol><li>${de ? "30 Minuten kennenlernen" : "A 30-minute introduction"}</li><li>${de ? "Aufgabe und Rahmen einordnen" : "Clarify the task and constraints"}</li><li>${de ? "Sinnvollen nächsten Schritt benennen" : "Name a useful next step"}</li></ol><p><strong>Clara Design Studio</strong><br>Schulterblatt 00<br>20357 Hamburg<br><a href="mailto:${copy[lang].email}">${copy[lang].email}</a></p></div><form class="contact-form" data-contact-form novalidate><div class="field"><label for="name">${de ? "Name" : "Name"} <span>(${copy[lang].required})</span></label><input id="name" name="name" autocomplete="name" data-required aria-describedby="name-error"><p class="field-error" id="name-error" hidden></p></div><div class="field"><label for="email">${de ? "E-Mail-Adresse" : "Email address"} <span>(${copy[lang].required})</span></label><input id="email" name="email" type="email" autocomplete="email" data-required aria-describedby="email-error"><p class="field-error" id="email-error" hidden></p></div><div class="field"><label for="organisation">${de ? "Organisation" : "Organisation"}</label><input id="organisation" name="organisation" autocomplete="organization"></div><div class="field"><label for="topic">${de ? "Worum geht es?" : "What would you like to discuss?"}</label><select id="topic" name="topic"><option>${de ? "Neue Website" : "New website"}</option><option>${de ? "Plone & Migration" : "Plone & migration"}</option><option>${de ? "Designsystem" : "Design system"}</option><option>${de ? "Pflege & Weiterentwicklung" : "Care & evolution"}</option></select></div><div class="field"><label for="message">${de ? "Ihre Ausgangslage" : "Your starting point"} <span>(${copy[lang].required})</span></label><textarea id="message" name="message" rows="6" data-required aria-describedby="message-help message-error"></textarea><p class="field-help" id="message-help">${de ? "Ein paar Sätze zu Inhalten, Team und gewünschtem Zeitraum reichen." : "A few sentences about your content, team and timing are enough."}</p><p class="field-error" id="message-error" hidden></p></div><button class="button button--coral" type="submit">${de ? "Anfrage als E-Mail vorbereiten" : "Prepare enquiry email"}</button><p class="form-status" data-form-status role="status" tabindex="-1" hidden></p></form></div></section></main>`;
}

function legal(route, lang) {
  const de = lang === "de";
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell legal prose"><h2>${de ? "Anbieter" : "Provider"}</h2><p>Clara Design Studio<br>${de ? "Fiktives Designprojekt" : "Fictional design project"}<br>Schulterblatt 00<br>20357 Hamburg</p><p><a href="mailto:${copy[lang].email}">${copy[lang].email}</a></p><h2>${de ? "Bildnachweise" : "Image credits"}</h2><p>${de ? "Alle Bilder stammen von Unsplash und werden in diesem nichtkommerziellen Referenzentwurf als Platzhalter verwendet." : "All photographs come from Unsplash and are used as placeholders in this non-commercial reference design."}</p><ul><li><a href="https://unsplash.com/@copernico">Copernico</a> — ${de ? "Studio und Hero" : "Studio and hero"}</li><li><a href="https://unsplash.com/@churchoftodd">Todd Kent</a> — ${de ? "Kulturprojekt" : "Culture project"}</li><li><a href="https://unsplash.com/@sunday_digital">Nastuh Abootalebi</a> — ${de ? "Öffentliches Projekt" : "Public project"}</li><li><a href="https://unsplash.com/@anniespratt">Annie Spratt</a> — ${de ? "Unternehmensprojekt" : "Business project"}</li><li><a href="https://unsplash.com/@scottwebb">Scott Webb</a> — ${de ? "Studio-Pflanzen" : "Studio plants"}</li></ul><p>${de ? "Quellbilder wurden lokal gespeichert und für diesen Entwurf zugeschnitten. Es werden keine Daten an Unsplash übertragen." : "Source images are stored locally and cropped for this design. No visitor data is sent to Unsplash."}</p></div></section></main>`;
}

function privacy(route, lang) {
  const de = lang === "de";
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><article class="shell legal prose"><h2>${de ? "Statischer Referenzentwurf" : "Static reference design"}</h2><p>${de ? "Diese Website ist ein lokaler Mockup. Sie verwendet weder Analysewerkzeuge noch externe Schriften, Bilder oder Skripte." : "This website is a local mockup. It uses no analytics and loads no external fonts, images or scripts."}</p><h2>${de ? "Kontaktformular" : "Contact form"}</h2><p>${de ? "Das Formular öffnet nach erfolgreicher Prüfung das E-Mail-Programm des Geräts. Eingaben werden nicht an diese Website übertragen oder gespeichert." : "After validation, the form opens the device's email application. Entries are not sent to or stored by this website."}</p></article></section></main>`;
}

function search(route, lang) {
  const de = lang === "de";
  return `<main id="main">${breadcrumbs(route, lang)}${pageHero(route, lang)}<section class="section"><div class="shell search-demo"><form role="search" data-search-form><label for="site-search">${de ? "Suchbegriff" : "Search term"}</label><div><input id="site-search" type="search" name="q" value="Plone"><button class="button button--ink" type="submit">${de ? "Suchen" : "Search"}</button></div></form><p class="result-count" aria-live="polite">${de ? "4 Ergebnisse für „Plone“" : "4 results for ‘Plone’"}</p><ul class="search-results">${["plone", "migration", "workflows", "editorialGuide"].map((key) => `<li><a href="${href(key, lang)}"><strong>${t(routes[key], lang).title}</strong><span>${t(routes[key], lang).context}</span><p>${t(routes[key], lang).lede}</p></a></li>`).join("")}</ul></div></section></main>`;
}

function notfound(route, lang) {
  const de = lang === "de";
  return `<main id="main">${pageHero(route, lang)}<section class="section"><div class="shell notfound"><p class="error-number" aria-hidden="true">404</p><div><h2>${de ? "Versuchen Sie einen dieser Wege" : "Try one of these paths"}</h2><ul><li><a href="${href("services", lang)}">${de ? "Leistungen" : "Services"}</a></li><li><a href="${href("projects", lang)}">${de ? "Projekte" : "Work"}</a></li><li><a href="${href("insights", lang)}">${de ? "Wissen" : "Insights"}</a></li><li><a href="${href("contact", lang)}">${de ? "Kontakt" : "Contact"}</a></li></ul></div></div></section></main>`;
}

function contactBand(lang) {
  return `<section class="contact-band"><div class="shell"><p>${lang === "de" ? "Lassen Sie uns anfangen." : "Let’s get started."}</p><h2>${copy[lang].contactTitle}</h2><span>${copy[lang].contactLead}</span><a class="button button--ink" href="${href("contact", lang)}">${copy[lang].projectCta}</a></div></section>`;
}

function footer(lang) {
  const c = copy[lang];
  return `<footer class="site-footer"><div class="shell footer-top"><div class="footer-brand"><a class="brand brand--footer" href="${href("home", lang)}"><span class="brand-window" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>Clara <b>Design Studio</b></span></a><p>${c.footerLine}</p><a href="mailto:${c.email}">${c.email}</a></div>${nav[lang].map((group) => `<div><h2><a href="${href(group.key, lang)}">${group.label}</a></h2><ul>${group.items.slice(0, 4).map(([key, label]) => `<li><a href="${href(key, lang)}">${label}</a></li>`).join("")}</ul></div>`).join("")}</div><div class="shell footer-bottom"><p>© 2026 Clara Design Studio</p><p>${c.rights}</p><ul><li><a href="${href("imprint", lang)}">${c.legal}</a></li><li><a href="${href("privacy", lang)}">${c.privacy}</a></li></ul></div></footer>`;
}

function body(route, lang) {
  if (route.type === "home") return home(route, lang);
  if (route.type === "overview") return overview(route, lang);
  if (["detail", "article"].includes(route.type)) return detail(route, lang);
  if (route.type === "projects") return projects(route, lang);
  if (route.type === "project") return project(route, lang);
  if (route.type === "insights") return insights(route, lang);
  if (route.type === "studio") return studio(route, lang);
  if (route.type === "contact") return contact(route, lang);
  if (route.type === "legal") return legal(route, lang);
  if (route.type === "privacy") return privacy(route, lang);
  if (route.type === "search") return search(route, lang);
  if (route.type === "notfound") return notfound(route, lang);
  return detail(route, lang);
}

function document(route, lang) {
  const text = t(route, lang);
  const title = `${text.title} · Clara Design Studio`;
  const includeContact = !["home", "contact", "notfound"].includes(route.key);
  return `<!doctype html><html lang="${lang}" class="no-js"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="description" content="${esc(text.lede)}"><meta name="theme-color" content="#f8df45"><title>${esc(title)}</title><link rel="preload" href="../assets/fonts/inclusive-sans-variable.ttf" as="font" type="font/ttf" crossorigin><script>(()=>{const v=new URLSearchParams(location.search).get("variant");if(["sunroom","greenhouse","open-sky"].includes(v))document.documentElement.dataset.variant=v})()</script><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/variants.css"><script>document.documentElement.classList.remove("no-js");document.documentElement.classList.add("js")</script><script src="../assets/site.js" defer></script></head><body>${header(route, lang)}${body(route, lang)}${includeContact ? contactBand(lang) : ""}${footer(lang)}</body></html>`;
}

for (const lang of ["de", "en"]) {
  await mkdir(join(root, lang), { recursive: true });
  for (const route of Object.values(routes)) {
    await writeFile(join(root, lang, route.slug[lang]), document(route, lang));
  }
}

await writeFile(join(root, "index.html"), `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0; url=en/index.html"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Clara Design Studio</title></head><body><p><a href="en/index.html">English</a> · <a href="de/index.html">Deutsch</a></p></body></html>`);
console.log(`Built ${Object.keys(routes).length * 2 + 1} Clara Design Studio pages.`);
